// Focused forms for the four payout types; existing calculations remain shared.
const payoutTypes=['Fixed','Unit-based'];
function payoutType(c){return c.uiType||(/MAX\(0,\s*value\s*-/.test(c.rules?.[0]?.formula||'')?'Minimum Guarantee':c.basis==='Per Unit'?'Unit-based':c.basis==='Performance'?'Performance-based':'Fixed')}
function readableFormula(c){return c.formula.replaceAll('value','Rate').replaceAll(c.primary||'___',displayKey(c.primary||''))}
structureForm=function(){modal(draft.name||'Create payout structure',`<div class="grid">${input('Structure name','name',draft.name)}${select('Evaluation period','period',['Daily','Weekly','Monthly'],draft.period,'The period used to calculate this payout.')}${select('User Type','userType',['All','OR','LMA','OFR','Agent'],draft.userType)}${select('Status','status',['Draft','Live'],draft.status)}</div><p class="quiet section-gap">${esc(draft.lob)} / ${esc(draft.entity)}</p>${draft.components.map(componentForm).join('')}<div class="actions">${btn('+ Add payment or deduction','add-component')}</div>`,btn('Save structure','save-structure','',true))};
function unitControls(c,i){const units=state.units.filter(u=>u.lob===draft.lob&&u.entity===draft.entity),u=state.units.find(u=>u.id===c.unit),attrs=u?.attributes.map(a=>({id:a.name,name:a.name.replaceAll('_',' ')}))||[];return `<div class="grid section-gap">${select('Unit',`components.${i}.unit`,[{id:'',name:'Select unit'},...units],c.unit)}${select('Rate selection',`components.${i}.lookup`,[{id:'Flat',name:'Flat rate'},{id:'1D Lookup',name:'By one attribute'},{id:'2D Lookup',name:'By two attributes'}],c.lookup)}</div>${c.lookup!=='Flat'?`<div class="grid section-gap">${select('Attribute 1',`components.${i}.attrs.0`,[{id:'',name:'Select attribute'},...attrs],c.attrs[0])}${c.lookup==='2D Lookup'?select('Attribute 2',`components.${i}.attrs.1`,[{id:'',name:'Select attribute'},...attrs],c.attrs[1]):''}</div>`:input('Rate per unit',`components.${i}.defaultValue`,c.defaultValue,'number')}<details><summary>Unit filter</summary><div class="grid3">${select('Attribute',`components.${i}.unitFilterKey`,[{id:'',name:'None'},...attrs],c.unitFilterKey)}${select('Operator',`components.${i}.unitFilterOp`,filterOps(u?.attributes.find(a=>a.name===c.unitFilterKey)?.type||'Character'),c.unitFilterOp)}${input('Values',`components.${i}.unitFilterValue`,c.unitFilterValue)}</div></details><div class="formula">Each qualifying unit × its selected rate</div>`}
function mgControls(c,i,manager=false){const r=c.rules[0];if(!r)return '';const ref=r.formula.match(/value\s*-\s*(\w+)/)?.[1]||'';const previous=draft.components.slice(0,i).map(x=>({id:x.id,name:x.name}));return `<div class="grid section-gap">${manager?`<label>Covered earnings<p>${esc(previous.find(x=>x.id===ref)?.name||ref||'Not selected')}</p></label>`:`<label>Covered earnings ${help('The earlier payment compared with the guarantee. Both use this evaluation period.')}<select data-mg-ref="${i}">${opts([{id:'',name:'Select payment'},...previous],ref)}</select></label>`}${input('Guaranteed amount',`components.${i}.rules.0.value`,r.value,'number')}</div><details ${r.max>0?'open':''}><summary>Eligibility target</summary><div class="grid">${manager?`<label>Performance key<p>${esc(displayKey(c.primary))}</p></label>`:select('Performance key',`components.${i}.primary`,sharedKeys,c.primary)}${input('Target ≥',`components.${i}.rules.0.max`,r.max,'number')}</div></details><div class="formula">Add only the difference needed to reach the guarantee.</div>`}
componentForm=function(c,i){const type=payoutType(c);return `<section class="panel component"><div class="panel-head"><h3>${esc(c.name)}</h3>${btn('Remove','remove-component',i)}</div><div class="panel-body"><div class="grid">${input('Name',`components.${i}.name`,c.name)}<label>Type<select data-simple-type="${i}">${opts(payoutTypes,type)}</select></label>${type==='Minimum Guarantee'?'<label>Operator<p>Add</p></label>':select('Operator',`components.${i}.effect`,['Add','Deduct'],c.effect)}</div>${type==='Fixed'?`<div class="section-gap">${input('Amount per '+({Daily:'day',Weekly:'week',Monthly:'month'})[draft.period],`components.${i}.defaultValue`,c.defaultValue,'number')}</div>${c.formula!=='value'?`<details><summary>Calculation</summary>${input('Formula',`components.${i}.formula`,c.formula)}${select('Value type',`components.${i}.valueType`,['Integer','Float','Percentage'],c.valueType)}</details>`:''}`:type==='Unit-based'?unitControls(c,i):type==='Minimum Guarantee'?mgControls(c,i):`<div class="grid section-gap">${select('Performance key',`components.${i}.primary`,sharedKeys,c.primary)}<label>Payment<select data-performance-mode="${i}">${opts(['Per quantity','By targets'],c.rules.length?'By targets':'Per quantity')}</select></label></div>${c.rules.length?ruleForm(c,i,false):`<div class="section-gap">${input('Rate',`components.${i}.defaultValue`,c.defaultValue,'number')}</div><div class="formula">${esc(readableFormula(c))}</div>`}<details><summary>Other keys and filters</summary><div class="field-list">${sharedKeys.filter(f=>f.id!==c.primary).map(f=>`<label><input type="checkbox" data-c-key="${i}|${f.id}" ${c.keys.includes(f.id)?'checked':''}>${esc(f.name)}</label>`).join('')}</div>${performanceFilters(c,i)}</details>`}</div></section>`};
ruleForm=function(c,i,manager){return `<div class="section-gap">${c.rules.map((r,j)=>`<div class="rule"><div class="rule-head"><h3>Slab ${j+1}</h3>${btn('Remove','remove-rule',`${i}|${j}`)}</div><div class="grid3">${input('From',`components.${i}.rules.${j}.min`,r.min,'number')}${input('To',`components.${i}.rules.${j}.max`,r.max,'number')}${input('Value',`components.${i}.rules.${j}.value`,r.value,'number')}</div><div class="grid section-gap">${select('Applicable when',`components.${i}.rules.${j}.when`,['Slab not achieved','Slab achieved','Both'],r.when)}${select('Stop when',`components.${i}.rules.${j}.exclude`,[{id:'NA',name:'Never'},{id:'Any subsequent slab achieved',name:'A later slab is achieved'}],r.exclude)}</div><label class="section-gap">Formula ${help('Use value, selected performance keys and + − × ÷. slab_quantity means progress within this band.')}<input data-k="components.${i}.rules.${j}.formula" value="${esc(r.formula)}"></label><details><summary>Additional condition and value type</summary><div class="grid">${select('Additional key',`components.${i}.rules.${j}.secondary`,[{id:'',name:'None'},...sharedKeys.filter(f=>c.keys.includes(f.id)&&f.id!==c.primary)],r.secondary||'')}${input('Target ≥',`components.${i}.rules.${j}.secondaryMax`,r.secondaryMax||0,'number')}${select('Value type',`components.${i}.rules.${j}.valueType`,['Integer','Float','Percentage'],r.valueType||'Float')}</div></details></div>`).join('')}${btn('+ Add slab','add-rule',i)}</div>`};
templateForm=function(){const s=structure(draft.structure);modal(draft.name||'Create template',`<div class="grid">${input('Template name','name',draft.name)}${select('Payout structure','structure',[{id:'',name:'Select structure'},...current(state.structures).filter(x=>x.status==='Live')],draft.structure)}</div>${s?`<p class="quiet section-gap">${esc(s.lob)} / ${esc(s.entity)} · ${s.period} · ${esc(s.userType)}</p>${draft.components.map((c,i)=>`<section class="panel"><div class="panel-head"><h3>${esc(c.name)}</h3><span class="tag">${payoutType(c)} · ${c.effect}</span></div><div class="panel-body">${payoutType(c)==='Minimum Guarantee'?mgControls(c,i,true):c.basis==='Per Unit'&&c.lookup!=='Flat'?`${table([...c.attrs.slice(0,c.lookup==='2D Lookup'?2:1).map(x=>esc(x.replaceAll('_',' '))),'Rate'],c.rates.map((r,j)=>row([...r.keys.map(esc),`<input type="number" step="any" data-k="components.${i}.rates.${j}.value" value="${r.value}" aria-label="${esc(r.keys.join(' '))} rate">`])))}${btn('+ Add rate','add-rate',i)}`:c.basis==='Performance'?`${c.rules.length?ruleForm(c,i,true):`${input('Rate',`components.${i}.defaultValue`,c.defaultValue,'number')}<div class="formula">${esc(readableFormula(c))}</div>${btn('+ Add slab','add-rule',i)}`}`:input(c.basis==='Fixed'?'Amount':'Rate per unit',`components.${i}.defaultValue`,c.defaultValue,'number')}</div></section>`).join('')}`:''}`,btn('Save template','save-template','',true))};
const oldStructureViewSimple=structureView;
structureView=function(){return title('Payout structures','Fixed · Unit-based · Performance-based · Minimum Guarantee',btn('+ Create structure','new-structure','',true))+`<div class="panel">${table(['Structure','Type','User Type','Evaluation','Status',''],current(state.structures).map(s=>row([`<strong>${esc(s.name)}</strong>`,[...new Set(s.components.map(payoutType))].map(t=>`<span class="tag">${t}</span>`).join(''),esc(s.userType),s.period,`<span class="pill ${s.status==='Live'?'live':''}">${s.status}</span>`,`<div class="actions">${btn('Open','edit-structure',s.id)}${btn('Duplicate','duplicate-structure',s.id)}</div>`])))}</div>`};
// These controls map the simple choices to the existing calculation model.
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.simpleType!==undefined){const i=Number(el.dataset.simpleType),c=draft.components[i],type=el.value;c.uiType=type;c.basis=type==='Fixed'?'Fixed':type==='Unit-based'?'Per Unit':'Performance';c.rules=[];c.formula='value';c.filters=[];c.skip=0;c.valueType='Float';if(type==='Unit-based'){const u=state.units.find(u=>u.lob===draft.lob&&u.entity===draft.entity);c.unit=u?.id||'';c.lookup='Flat';c.attrs=[];c.unitFilterKey='';}if(type==='Performance-based'){c.primary=sharedKeys[0]?.id||'';c.keys=[c.primary];c.formula='value * '+c.primary;}if(type==='Minimum Guarantee'){c.effect='Add';c.primary=sharedKeys[0]?.id||'';c.keys=[c.primary];c.rules=[slab(0,1,0,'MAX(0, value - '+(draft.components[i-1]?.id||'covered_earnings')+')')];}structureForm();return}if(el.dataset.performanceMode!==undefined){const c=draft.components[Number(el.dataset.performanceMode)];c.rules=el.value==='By targets'?[slab(0,50,0)]:[];c.formula='value * '+c.primary;structureForm();return}if(el.dataset.mgRef!==undefined){draft.components[Number(el.dataset.mgRef)].rules[0].formula='MAX(0, value - '+el.value+')';structureForm();return}if(el.dataset.k?.endsWith('.primary')){const c=draft.components[Number(el.dataset.k.split('.')[1])];if(c&&payoutType(c)==='Performance-based'&&!c.rules.length){c.keys=[c.primary];c.formula='value * '+c.primary;structureForm();}}});
render();

const originalCompSimple=comp;comp=function(id,name,basis='Fixed',extra={}){return {...originalCompSimple(id,name,basis,extra),...(!Object.keys(extra).length?{unit:'',attrs:[],unitFilterKey:'',primary:sharedKeys[0]?.id||'',keys:[sharedKeys[0]?.id||'']}:{} )}};
